static void smartfiresystem_eventqueue_init(smartfiresystem_eventqueue * eq, smartfiresystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smartfiresystem_eventqueue_size(smartfiresystem_eventqueue * eq)
{
	return eq->size;
}

static smartfiresystem_event smartfiresystem_eventqueue_pop(smartfiresystem_eventqueue * eq)
{
	smartfiresystem_event event;
	if(smartfiresystem_eventqueue_size(eq) <= 0) {
		smartfiresystem_event_init(&event, SmartFireSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smartfiresystem_eventqueue_push(smartfiresystem_eventqueue * eq, smartfiresystem_event ev)
{
	if(smartfiresystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smartfiresystem_event_init(smartfiresystem_event * ev, SmartFireSystemEventID name)
{
	ev->name = name;
}

static void smartFireSystem_add_event_to_queue(smartfiresystem_eventqueue * eq, SmartFireSystemEventID name)
{
	smartfiresystem_event event;
	smartfiresystem_event_init(&event, name);
	smartfiresystem_eventqueue_push(eq, event);
}

